    ls=(text or "").splitlines()
    for i,l in enumerate(ls):
        m=re.match(r"^- \[[ x~]\] (.*)$",l)
        if m and m.group(1).strip().startswith(key):
            out=[l]
            for k in range(i+1,len(ls)):
                if ls[k].startswith("  "): out.append(ls[k])
                else: break
            return "\n".join(out)
    return None
